import React, { useState,useEffect } from "react";
import { MpaLogo } from "../logo/MpaLogo";
import "./FooterDesktop.scss";
import { MpaIcon } from "../icon/MpaIcon";
import {SvgMpaIcon,SvgMpaLogo} from "../../assets/icons/index";

export interface FooterDesktopProps {
  /**
   * The name of the primary title in the footer.
   */
  portalName?: string;
  /**
   * The description of the application underneath the primary title.
   */
  portalDescription?: string;
  /**
     * Logo to be rendered under the "Powered by" text.
     */
  poweredByLogo?: keyof typeof SvgMpaLogo | string;
  /**
   * An array of objects representing the columns.
   * Each object should have `label` and `links` properties.
   * `label` represents the name of the column, and `links` is an array of objects representing the links in that column.
   * Each link object should have `text` and `link` properties.
   */
  columns?: { label: string; links: { text: string; link: string }[] }[];
  /**
   * An array of objects representing the footer bottom link.
   * Each object should have `links` properties.
   * `links` is an array of objects representing the links in that footer bottom link.
   * Each link object should have `text` and `link` properties.
   */
  footerBottomLink?: { links: { text: string; link: string }[] }[];
  /**
   * An array of objects representing the footer link.
   * Each object should have `links` properties.
   * `links` is an array of objects representing the links in that footer link.
   * Each link object should have `text` and `link` properties.
   */
  footerLink?: { links: { text: string; link: string }[] }[];
  /**
   * Redirect link for footer copy right message.
   */
  footerCopy?: string;
  /**
  * Redirect link for last updated date.
  */
  lastUpdated?: string;
  /**
   * An array of objects representing the footer link.
   * Each object should have `links` properties.
   * `links` is an array of objects representing the links in that footer link.
   * Each link object should have `text` and `link` properties.
   */
  socialLink?: { icon?: keyof typeof SvgMpaIcon | string; link: string }[];
}

export const FooterDesktop: React.FC<FooterDesktopProps> = ({
  portalName,
  portalDescription,
  poweredByLogo = "MpaWhiteLogo",
  columns,
  footerBottomLink,
  footerLink,
  footerCopy,
  lastUpdated,
  socialLink = [
    {
      icon: "BrandYoutube",
      link: "https://www.youtube.com/c/MPASingaporeOfficial"
    },
    {
      icon: "BrandTwitter",
      link: "https://twitter.com/mpa_singapore"
    },
    {
      icon: "Instagram_SGDS",
      link: "https://www.instagram.com/maritime_sg/?hl=en",
    },
    {
      icon: "BrandLinkedIn",
      link: "https://www.linkedin.com/company/mpasingapore",
    },
    {
      icon: "BrandFacebook",
      link: "https://www.facebook.com/MPA.SG",
    },
    {
      icon: "BrandTiktok", 
      link: "https://www.tiktok.com/@maritimesg"
    }
  ]
}) => {
  if (columns && columns.length > 4) {
    throw new Error("Maximum of 3 columns allowed in Footer component.");
  }

  const [windowWidth, setWindowWidth] = useState(window.innerWidth);

  useEffect(() => {
    const handleResize = () => setWindowWidth(window.innerWidth);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);
  const isMobile = windowWidth < 768;
  const [openIndex, setOpenIndex] = useState<number | null>(null);
  const toggleSection = (index: number) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  return (    
    <footer className="footer">
      <div className="footer-top">
        <div className={`${!isMobile ? "footer-about" : ""}`}>
          <h2>{portalName}</h2>
          <p>
            {portalDescription}
          </p>
          <div className="footer-powered">
            <strong>Powered by</strong>
            <br />
            <br />
            {<MpaLogo logoName={poweredByLogo} width={100} height={100}/>}
          </div>
        </div>        
        <div className={`${!isMobile ? "footer-columns" : ""}`}>        
          <div className="footer-columns-mobile">
            {columns &&
              columns.map((column, columnIndex) => (
                <div key={columnIndex} className="footer-column-mobile">
                  <div
                    className="footer-header-mobile"
                    onClick={() => toggleSection(columnIndex)}
                  >
                    <h3>{column.label}</h3>
                    {isMobile && ( 
                      <span className="toggle-icon-mobile">
                        {openIndex === columnIndex ? 
                          <MpaIcon iconName="ChevronUp" size={18}/> : 
                          <MpaIcon iconName="ChevronDown" size={18}/>
                        }
                      </span>
                    )}                    
                  </div>
                  <ul className={`footer-links-mobile ${openIndex === columnIndex ? "open" : ""}`}>
                    {column.links.map((item, itemIndex) => (
                      <li key={itemIndex}>
                        <a href={item.link}>{item.text}</a>
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
          </div>
        </div>
      </div>

      <div className={`${!isMobile ? "footer-mid" : "footer-mid-mobile-version"}`}>
        {footerLink &&
          footerLink.map((footer,i) => (
            <ul key={`footerLink-${i}`} className={`${!isMobile ? "footer-links" : "footer-links-mobile-version"}`}>
              {footer.links.map((item, itemIndex) => (
                <li key={itemIndex}>
                  <a href={item.link}>{item.text}</a>
                </li>
              ))}
            </ul>

          ))}
        <ul key={`footer-socials`} className="footer-socials">
          {socialLink &&
            socialLink.map((social,index) => (
              <li key={index}>
                 <a href={social.link} target="_blank" rel="noopener noreferrer">
                  {social.icon && <MpaIcon iconName={social.icon} />}
                </a>
              </li>
            ))
          }
        </ul>
      </div>      
      <hr />
      <div className="footer-bottom">
        {footerBottomLink &&
          footerBottomLink.map((footer,i) => (
            <ul  key={`footer-bottom-${i}`}
              className={`${!isMobile ? "footer-policy" : "footer-policy-mobile-version"}`}>
              {footer.links.map((item, itemIndex) => (
                <li key={itemIndex}>
                  <a href={item.link}>{item.text}</a>
                </li>
              ))}
            </ul>
          ))}
        <div className={`${!isMobile ? "footer-copy" : "footer-copy-mobile-version"}`}>
          <strong>{footerCopy}</strong>
          <p>{lastUpdated}</p>
        </div>
      </div>
    </footer>
  );
};

export default FooterDesktop;
